from pathlib import Path
p=Path("index.html")
s=p.read_text()

def rep(old,new,count=1):
    global s
    if s.count(old)!=count:
        raise SystemExit(f"target count mismatch: {old[:80]!r} => {s.count(old)}")
    s=s.replace(old,new,count)

rep('.app{min-height:100vh}','.app{min-height:100vh;display:none}.app.authenticated{display:block}')
rep('</head>', '  <style>\n    .login-screen{min-height:100vh;display:grid;place-items:center;padding:24px;background:\n      radial-gradient(circle at 20% 15%,rgba(255,90,22,.13),transparent 34%),\n      radial-gradient(circle at 80% 85%,rgba(217,241,92,.06),transparent 30%),var(--bg)}\n    .login-card{width:min(430px,100%);padding:28px;background:var(--panel);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow)}\n    .login-brand{display:flex;align-items:center;gap:12px;margin-bottom:28px}.login-brand .brand-mark{flex:none}\n    .login-card .eyebrow{display:block;margin-bottom:8px}.login-card h1{margin:0;font:800 42px/.92 "Barlow Condensed";text-transform:uppercase}\n    .login-card p{margin:10px 0 22px;color:var(--muted);font-size:12px;line-height:1.55}\n    .login-mode{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:14px}.login-mode-button{min-height:40px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--panel-2);color:var(--muted);font-size:10px;font-weight:900}.login-mode-button.active{background:#2d1b13;border-color:var(--orange);color:var(--orange-soft)}.login-form{display:grid;gap:12px}.login-field{display:grid;gap:7px}.login-field label{color:#d9cec3;font-size:11px;font-weight:800}\n    .login-input,.account-input{width:100%;height:46px;padding:0 13px;background:var(--panel-2);border:1px solid var(--line);border-radius:9px;color:var(--text);font:12px Manrope,sans-serif}\n    .login-input::placeholder,.account-input::placeholder{color:#756d66}.login-form .button{width:100%;min-height:46px;margin-top:4px}\n    .auth-message{min-height:18px;margin-top:12px;color:var(--red);font-size:11px;line-height:1.45}.auth-message.success{color:var(--lime)}\n    .login-help{margin-top:18px;padding-top:15px;border-top:1px solid var(--line);color:#7f766f;font-size:10px;line-height:1.55}\n    button.user{background:transparent;cursor:pointer;text-align:left}.user:hover{color:var(--text)}.user:focus-visible{border-radius:9px}\n    .account-role{display:inline-flex;margin-top:5px;padding:4px 7px;border-radius:6px;background:#2d1b13;color:var(--orange-soft);font-size:9px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}\n    .account-section{padding:15px;background:var(--panel-2);border:1px solid var(--line);border-radius:10px;margin-top:12px}\n    .account-section h3{margin:0 0 6px;font:800 21px/1 "Barlow Condensed";text-transform:uppercase}.account-section p{margin:0 0 13px;color:var(--muted);font-size:10px;line-height:1.5}\n    .account-form{display:grid;gap:9px}.account-form .button{margin-top:2px}.account-status{min-height:16px;color:var(--muted);font-size:10px;line-height:1.4}\n    .account-status.error{color:var(--red)}.account-status.ok{color:var(--lime)}\n    .account-footer{display:flex;gap:8px;margin-top:14px}.account-footer .button{flex:1}\n    @media(max-width:700px){.login-card{padding:22px}.login-card h1{font-size:36px}.login-screen{padding:16px}.account-footer{flex-direction:column}}\n  </style>\n' + '</head>')
rep('<body>\n  <div class="app">','<body>\n\n' + '  <section class="login-screen" id="login-screen">\n    <div class="login-card">\n      <div class="login-brand"><span class="brand-mark">LV</span><span class="brand-copy"><strong>DELIVERY</strong><small>PAINEL ADMINISTRATIVO</small></span></div>\n      <span class="eyebrow">Acesso protegido</span>\n      <h1>Entrar no painel</h1>\n      <p>Entre com o e-mail e a senha cadastrados.</p>\n      <form class="login-form" id="login-form">\n        <div class="login-field" id="login-user-field">\n          <label for="login-user">E-mail</label>\n          <input class="login-input" id="login-user" type="email" autocomplete="username" placeholder="Digite o e-mail cadastrado">\n        </div>\n        <div class="login-field">\n          <label for="login-password" id="login-password-label">Senha</label>\n          <input class="login-input" id="login-password" type="password" autocomplete="current-password" placeholder="Digite sua senha" required>\n        </div>\n        <button class="button" id="login-submit" type="submit"><i data-lucide="log-in"></i><span id="login-submit-label">Entrar</span></button>\n      </form>\n      <div class="auth-message" id="login-message" role="status" aria-live="polite"></div>\n      <div class="login-help">Por segurança, a senha não fica gravada no código do site. Após tentativas incorretas repetidas, o acesso é temporariamente bloqueado.</div>\n    </div>\n  </section>\n' + '  <div class="app" id="panel-app">')
