rep("  const db=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY);\n", "  const PANEL_SESSION_KEY='deliverylv_panel_session';\n  const createPanelClient=token=>window.supabase.createClient(\n    SUPABASE_URL,\n    SUPABASE_PUBLISHABLE_KEY,\n    token?{global:{headers:{'x-panel-session':token}}}:{}\n  );\n  let panelToken=localStorage.getItem(PANEL_SESSION_KEY)||'';\n  let panelProfile=null;\n  let db=createPanelClient(panelToken);\n  const publicDb=createPanelClient('');\n  async function panelAuth(action,{login=null,password=null,newPassword=null}={}){\n    const client=action==='login'?publicDb:db;\n    const {data,error}=await client.rpc('lv_panel_auth',{\n      p_action:action,\n      p_login:login,\n      p_password:password,\n      p_new_password:newPassword\n    });\n    if(error)throw error;\n    return data;\n  }\n")
old_init="  async function init(){await loadDailyCosts();await loadExpenses();await loadRealOrders({notify:false});loadRealMenu();subscribeToOrders();startOrdersRefresh();if(location.hash==='#finance')switchView('finance')}\n  init().catch(error=>{console.error('Erro ao iniciar painel:',error);showToast('Erro ao iniciar painel')});\n"
rep(old_init,"  async function initPanel(){\n    await loadDailyCosts();\n    await loadExpenses();\n    await loadRealOrders({notify:false});\n    loadRealMenu();\n    subscribeToOrders();\n    startOrdersRefresh();\n    if(location.hash==='#finance')switchView('finance');\n  }\n\n  function showLogin(message=''){\n    document.querySelector('#panel-app').classList.remove('authenticated');\n    document.querySelector('#login-screen').style.display='grid';\n    const status=document.querySelector('#login-message');\n    status.textContent=message;\n    document.querySelector('#login-password').value='';\n    lucide.createIcons();\n  }\n\n  function renderPanelProfile(profile){\n    panelProfile=profile;\n    const isSuper=profile?.role==='superadmin';\n    document.querySelector('#account-label').textContent=isSuper?'Super Admin':'Proprietária';\n    document.querySelector('#account-avatar').textContent=isSuper?'JJ':'LV';\n    document.querySelector('#account-role').textContent=isSuper?'Super Admin':'Proprietária';\n    document.querySelector('#account-title').textContent=isSuper?'Acesso superior':'Acesso da proprietária';\n    document.querySelector('#account-description').textContent=isSuper\n      ?`Usuário conectado: ${profile.login}. Você pode administrar o acesso da proprietária.`\n      :`Conta conectada: ${profile.login}.`;\n    const ownerSection=document.querySelector('#owner-section');\n    ownerSection.style.display=isSuper?'block':'none';\n    if(isSuper){\n      const ownerExists=Boolean(profile.owner_login);\n      document.querySelector('#owner-form').style.display=ownerExists?'none':'grid';\n      document.querySelector('#owner-description').textContent=ownerExists\n        ?`A conta da proprietária já está cadastrada: ${profile.owner_login}`\n        :'Cadastre o e-mail e uma senha inicial para a dona da Delivery LV.';\n      document.querySelector('#owner-status').textContent='';\n      document.querySelector('#owner-status').className='account-status';\n    }\n    lucide.createIcons();\n  }\n\n  async function enterPanel(profile){\n    renderPanelProfile(profile);\n    document.querySelector('#login-screen').style.display='none';\n    document.querySelector('#panel-app').classList.add('authenticated');\n    try{\n      await initPanel();\n    }catch(error){\n      console.error('Erro ao iniciar painel:',error);\n      showToast('Erro ao iniciar painel');\n    }\n  }\n\n  async function clearPanelSession({serverLogout=false,message=''}={}){\n    if(serverLogout&&panelToken){\n      try{await panelAuth('logout')}catch(error){console.warn('Não foi possível encerrar a sessão no servidor:',error)}\n    }\n    if(ordersChannel){try{await db.removeChannel(ordersChannel)}catch(error){} ordersChannel=null}\n    if(ordersRefreshTimer){clearInterval(ordersRefreshTimer);ordersRefreshTimer=null}\n    panelToken='';\n    panelProfile=null;\n    localStorage.removeItem(PANEL_SESSION_KEY);\n    db=createPanelClient('');\n    document.querySelector('#account-modal').classList.remove('show');\n    showLogin(message);\n  }\n\n  document.querySelector('#login-form').onsubmit=async event=>{\n    event.preventDefault();\n    const typedLogin=document.querySelector('#login-user').value.trim();\n    const password=document.querySelector('#login-password').value;\n    const login=typedLogin||'jhonata';\n    const button=document.querySelector('#login-submit');\n    const status=document.querySelector('#login-message');\n    if(!password)return;\n    button.disabled=true;\n    status.textContent='Verificando acesso...';\n    status.className='auth-message';\n    try{\n      const result=await panelAuth('login',{login,password});\n      if(!result?.ok){\n        status.textContent=result?.message||'Usuário ou senha inválidos.';\n        return;\n      }\n      panelToken=result.token;\n      localStorage.setItem(PANEL_SESSION_KEY,panelToken);\n      db=createPanelClient(panelToken);\n      const me=await panelAuth('me');\n      if(!me?.ok)throw new Error(me?.message||'Não foi possível validar a sessão.');\n      status.textContent='';\n      await enterPanel(me);\n    }catch(error){\n      console.error('Erro no login:',error);\n      status.textContent='Não foi possível entrar agora. Verifique sua conexão e tente novamente.';\n    }finally{\n      button.disabled=false;\n    }\n  };\n\n  document.querySelector('#account-button').onclick=async()=>{\n    try{\n      const me=await panelAuth('me');\n      if(!me?.ok){await clearPanelSession({message:'Sua sessão terminou. Entre novamente.'});return}\n      renderPanelProfile(me);\n      document.querySelector('#account-modal').classList.add('show');\n      lucide.createIcons();\n    }catch(error){\n      console.error('Erro ao abrir conta:',error);\n      showToast('Não foi possível abrir sua conta');\n    }\n  };\n\n  document.querySelector('#close-account').onclick=()=>document.querySelector('#account-modal').classList.remove('show');\n  document.querySelector('#account-modal').addEventListener('click',event=>{if(event.target.id==='account-modal')event.currentTarget.classList.remove('show')});\n\n  document.querySelector('#owner-form').onsubmit=async event=>{\n    event.preventDefault();\n    const email=document.querySelector('#owner-email').value.trim();\n    const password=document.querySelector('#owner-password').value;\n    const status=document.querySelector('#owner-status');\n    const button=event.submitter;\n    if(!email||password.length<8)return;\n    button.disabled=true;\n    status.textContent='Criando acesso...';\n    status.className='account-status';\n    try{\n      const result=await panelAuth('create_owner',{login:email,newPassword:password});\n      status.textContent=result?.message||'Acesso atualizado.';\n      status.className=`account-status ${result?.ok?'ok':'error'}`;\n      if(result?.ok){\n        event.target.reset();\n        const me=await panelAuth('me');\n        if(me?.ok)renderPanelProfile(me);\n        document.querySelector('#owner-status').textContent=result.message;\n        document.querySelector('#owner-status').className='account-status ok';\n      }\n    }catch(error){\n      console.error('Erro ao cadastrar proprietária:',error);\n      status.textContent='Não foi possível cadastrar o acesso.';\n      status.className='account-status error';\n    }finally{button.disabled=false}\n  };\n\n  document.querySelector('#password-form').onsubmit=async event=>{\n    event.preventDefault();\n    const current=document.querySelector('#current-password').value;\n    const next=document.querySelector('#new-password').value;\n    const status=document.querySelector('#password-status');\n    const button=event.submitter;\n    if(!current||next.length<8)return;\n    button.disabled=true;\n    status.textContent='Alterando senha...';\n    status.className='account-status';\n    try{\n      const result=await panelAuth('change_password',{password:current,newPassword:next});\n      if(!result?.ok){\n        status.textContent=result?.message||'Não foi possível alterar a senha.';\n        status.className='account-status error';\n        return;\n      }\n      status.textContent=result.message;\n      status.className='account-status ok';\n      event.target.reset();\n      setTimeout(()=>clearPanelSession({message:'Senha alterada. Entre novamente com a nova senha.'}),700);\n    }catch(error){\n      console.error('Erro ao trocar senha:',error);\n      status.textContent='Não foi possível alterar a senha.';\n      status.className='account-status error';\n    }finally{button.disabled=false}\n  };\n\n  document.querySelector('#logout-button').onclick=()=>clearPanelSession({serverLogout:true});\n\n  async function boot(){\n    lucide.createIcons();\n    if(!panelToken){showLogin();return}\n    try{\n      db=createPanelClient(panelToken);\n      const me=await panelAuth('me');\n      if(!me?.ok){await clearPanelSession({message:'Entre novamente para acessar o painel.'});return}\n      await enterPanel(me);\n    }catch(error){\n      console.error('Erro ao restaurar sessão:',error);\n      await clearPanelSession({message:'Entre novamente para acessar o painel.'});\n    }\n  }\n  boot();\n")
